-- Westfield Recreation and Park District (at large, 4 seats; RR/CC DST PARK WE; https://wprpd.specialdistrict.org/board-members):
--   Director: Mirta Abel -- appointed 2022-12-01 (month)
--   Director: Gerald D. Melton -- appointed 2022-12-01 (month)
--   Director: Peter Michel -- appointed 2022-12-01 (month)
--   Director: Alan R. Hoffman -- appointed 2024-12-01 (month)
--
-- BATCH NOTES:
--   ON THE BALLOT (3 races / 11 candidates): La Cañada ID Division 4; Altadena Library Trustee Area 3 (first area
--     election; no incumbent); Palos Verdes Library (3 at-large seats, 6 candidates; Rosa Kwon Easton did not file).
--   APPOINTED IN LIEU (no race): Kinneloa Div 2 and 3; La Cañada Div 1; Palm Ranch Div 4 (and Div 2: NO ONE took papers,
--     so the Board of Supervisors appoints; Valasek stays seated); South Montebello Div 1 and 2; AV Healthcare District 3
--     and 5 -- RR/CC Notice of No Election (AV Press 2026-08-27); Beach Cities (2 for 2); Altadena Trustee Area 4
--     (Ruffin); Westfield (3 for 3) -- RR/CC Notice of No Election (PV Peninsula News 2026-09-03).
--   AV HEALTHCARE DISTRICT is switching to 5 zones (Ordinance 073025, map 'Olive C'): Districts 3 and 5 are first filled
--     Dec 2026 (by appointment in lieu), Districts 1, 2, 4 in 2028. Today all 5 directors were elected AT LARGE, so they
--     are modeled on one whole-district polygon; the zone seats get added when they take office. Hofbauer won the 3rd seat
--     of the 2024 vote-for-three contest.
--   ALTADENA LIBRARY is mid-transition to trustee areas (Resolution 2023-03): TA 1, 2, 5 have area trustees; Mahramas
--     and Ruffin hold AT-LARGE holdover seats (whole-district polygon, 'Trustee (At-Large)'); TA 3 gets a new vacant area
--     seat that carries the Nov 2026 race; TA 4 (first filled Dec 2026 by appointment in lieu -- Ruffin) is not created
--     yet. The gate's partition and end-to-end checks compare area seats with area seats and at-large with at-large.
--   WESTFIELD: 5 directors, but only 4 can be named from public sources (RR/CC 2022/2024 lists + the 2026 no-election
--     notice); the fifth (2024 cycle; the 2024 incumbent Brenda Lee Swanney Caropino did not file) is NOT modeled. The Nov
--     2026 list's 'JERRY D. MELTON' is the 2022 list's GERALD D. MELTON.
--   PETER MICHEL (Westfield director) also runs for Palos Verdes Library with the ballot designation 'Member, Board of
--     Directors, Westfield Recreation and Park District' -- same person, one politician row, linked as a non-incumbent
--     PVLD candidate.
--   NAMESAKE: La Cañada ID's Richard H. Myers, Jr. shares first+last name with an Indiana sheriff row (7a42825f,
--     'Richard W Myers', ballotready) -- a different person; inserted with the duplicate-name guard override for that one
--     statement.
--   REUSED ROW: Katie Clark (2024 NetFile filer row).
--   Palm Ranch and South Montebello: two appointees' appointment dates are not published (term_start NULL, precision
--     unknown); Palm Ranch divisions come from the RR/CC 2022/2024 lists because the district site lists officers only.
BEGIN;

-- ─── 1. Government + governing board (chamber) per special district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, 'Kinneloa Irrigation District, California, US'),
    ('231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'La Cañada Irrigation District, California, US'),
