-- Namesakes that are DIFFERENT people (checked; see batch notes): insert with the duplicate-name guard
-- override scoped to this one statement, then switch it back on.
SELECT set_config('essentials.allow_duplicate_name', 'on', true);
INSERT INTO essentials.politicians (id, first_name, last_name, full_name, party, party_short_name,
                                    is_active, is_incumbent, is_vacant, is_appointed, data_source)
SELECT v.id, v.first_name, v.last_name, v.full_name, NULL, NULL, true, true, false, v.appt, v.url
  FROM (VALUES
    ('410e1685-9d85-5020-8e47-b03a3a475764'::uuid, 'Richard', 'Myers', 'Richard H. Myers, Jr.', true, 'https://www.lcidwater.com/our-board/')
  ) AS v(id, first_name, last_name, full_name, appt, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.id = v.id);
SELECT set_config('essentials.allow_duplicate_name', 'off', true);

-- Reused rows (same people already in the DB): mark active incumbent, clear any stored party.
UPDATE essentials.politicians p SET is_incumbent = true, is_active = true, party = NULL, party_short_name = NULL
 WHERE p.id IN ('b1322418-06f8-4942-8b32-d2e09e90f4e9')
   AND (NOT p.is_incumbent OR NOT p.is_active OR p.party IS NOT NULL OR p.party_short_name IS NOT NULL);

