-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X-CA-SPD' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry) AND public.ST_SRID(gb.geometry) = 4326;
  IF n <> 27 THEN RAISE EXCEPTION 'expected 27 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid) AND d.district_type = 'LOCAL' AND d.mtfcc = 'X-CA-SPD';
  IF n <> 27 THEN RAISE EXCEPTION 'expected 27 LOCAL districts, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE d.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid);
  IF n <> 43 THEN RAISE EXCEPTION 'expected 43 offices, got %', n; END IF;

  -- every held seat is held by exactly the director named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('560daaaa-e052-574c-94ae-27dec60d83bb'::uuid, 'c441a0d6-e6fd-5903-ad7c-c856e28dea49'::uuid), ('6b2e9b63-df4f-5480-a513-3bcabc318594'::uuid, '537657fa-751f-5afd-ab90-f322ff59a6dd'::uuid), ('b376b221-442e-5f84-8c7a-5d7e4ee807ec'::uuid, 'c02cb88c-d66a-58d0-a172-906918fc9ab5'::uuid), ('03f394cd-91bf-5c82-acfc-22bc74f2fbd8'::uuid, '8d56add4-56af-5ce7-a169-1df38136e6f8'::uuid), ('38797133-ee79-55f6-93e4-d137523723de'::uuid, '01a625e7-f3ba-538d-8ec0-fb627ce190de'::uuid), ('85afaff1-6b69-56fa-aef1-3f3556c4bd5c'::uuid, '410e1685-9d85-5020-8e47-b03a3a475764'::uuid), ('b7d887ca-22c5-51fc-a46d-429d269ae349'::uuid, '3dd2c797-cfd2-5444-b8fc-86b5bee1f284'::uuid), ('b9d4e93c-f637-5b0a-b9dd-b532a9a98192'::uuid, '947d49a4-158e-5484-8bc7-7111358bde9a'::uuid), ('6a364a48-00d3-551f-89a8-dc6e9336065e'::uuid, '3f9c9035-c8c5-55c9-b338-e68e21db5e3a'::uuid), ('b87bc7f4-a364-57d4-90ab-2e7b836d045d'::uuid, 'e3261ebc-d803-58d5-9635-1162e5902146'::uuid), ('acb1c9be-22ca-5ccb-b488-f14382791495'::uuid, 'ffed0a3b-1cd8-5327-960e-c6ffa2f3875a'::uuid), ('313e6920-6ddb-5393-ac5a-cab54086041a'::uuid, '0b4d0628-0265-5e7c-ab5b-fd0dfaa379c1'::uuid), ('f5ac65b1-91fc-55ce-935c-15e0d4c626da'::uuid, 'da18f742-8423-5c7c-b3e3-d64f21eae735'::uuid), ('21355f02-f40f-50b9-9fe2-94616070aa01'::uuid, '5b39eb59-55ba-5bb9-ac49-206c2b269cd8'::uuid), ('92eaa733-5178-563c-9f57-1c97b4f9d582'::uuid, '1489605a-8847-540a-8dea-da2db9c2d89d'::uuid), ('b9795fc3-51bf-5e02-8a55-41d4750f10ee'::uuid, '86d59fe7-ca3f-5c98-ab72-05ce5fc8fc19'::uuid), ('218c4873-a909-5081-b7ad-256142f6857d'::uuid, '24990936-8c2f-5509-9323-da2faa9ec400'::uuid), ('03a243de-5f49-53a2-978b-bde3a4002b75'::uuid, 'ace32b44-4311-567b-97ea-622d2c1498e9'::uuid), ('5f4f6ccc-d7a9-5bcb-b153-71d9038c2a03'::uuid, 'cab02c09-3b89-5980-a89f-834ca4b06ff6'::uuid), ('7075f851-e412-521a-a47c-f55e27aab562'::uuid, '68d26472-f0a4-55c0-ae9d-75ad6c35387f'::uuid), ('a8b1f487-8bfc-53e9-b73a-144686ba9a86'::uuid, '8928c626-36a6-542b-80d6-dcadd03aeb