    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 42 THEN RAISE EXCEPTION 'expected 42 seats each held by its named director, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('560daaaa-e052-574c-94ae-27dec60d83bb'::uuid, 'c441a0d6-e6fd-5903-ad7c-c856e28dea49'::uuid), ('6b2e9b63-df4f-5480-a513-3bcabc318594'::uuid, '537657fa-751f-5afd-ab90-f322ff59a6dd'::uuid), ('b376b221-442e-5f84-8c7a-5d7e4ee807ec'::uuid, 'c02cb88c-d66a-58d0-a172-906918fc9ab5'::uuid), ('03f394cd-91bf-5c82-acfc-22bc74f2fbd8'::uuid, '8d56add4-56af-5ce7-a169-1df38136e6f8'::uuid), ('38797133-ee79-55f6-93e4-d137523723de'::uuid, '01a625e7-f3ba-538d-8ec0-fb627ce190de'::uuid), ('85afaff1-6b69-56fa-aef1-3f3556c4bd5c'::uuid, '410e1685-9d85-5020-8e47-b03a3a475764'::uuid), ('b7d887ca-22c5-51fc-a46d-429d269ae349'::uuid, '3dd2c797-cfd2-5444-b8fc-86b5bee1f284'::uuid), ('b9d4e93c-f637-5b0a-b9dd-b532a9a98192'::uuid, '947d49a4-158e-5484-8bc7-7111358bde9a'::uuid), ('6a364a48-00d3-551f-89a8-dc6e9336065e'::uuid, '3f9c9035-c8c5-55c9-b338-e68e21db5e3a'::uuid), ('b87bc7f4-a364-57d4-90ab-2e7b836d045d'::uuid, 'e3261ebc-d803-58d5-9635-1162e5902146'::uuid), ('acb1c9be-22ca-5ccb-b488-f14382791495'::uuid, 'ffed0a3b-1cd8-5327-960e-c6ffa2f3875a'::uuid), ('313e6920-6ddb-5393-ac5a-cab54086041a'::uuid, '0b4d0628-0265-5e7c-ab5b-fd0dfaa379c1'::uuid), ('f5ac65b1-91fc-55ce-935c-15e0d4c626da'::uuid, 'da18f742-8423-5c7c-b3e3-d64f21eae735'::uuid), ('21355f02-f40f-50b9-9fe2-94616070aa01'::uuid, '5b39eb59-55ba-5bb9-ac49-206c2b269cd8'::uuid), ('92eaa733-5178-563c-9f57-1c97b4f9d582'::uuid, '1489605a-8847-540a-8dea-da2db9c2d89d'::uuid), ('b9795fc3-51bf-5e02-8a55-41d4750f10ee'::uuid, '86d59fe7-ca3f-5c98-ab72-05ce5fc8fc19'::uuid), ('218c4873-a909-5081-b7ad-256142f6857d'::uuid, '24990936-8c2f-5509-9323-da2faa9ec400'::uuid), ('03a243de-5f49-53a2-978b-bde3a4002b75'::uuid, 'ace32b44-4311-567b-97ea-622d2c1498e9'::uuid), ('5f4f6ccc-d7a9-5bcb-b153-71d9038c2a03'::uuid, 'cab02c09-3b89-5980-a89f-834ca4b06ff6'::uuid), ('7075f851-e412-521a-a47c-f55e27aab562'::uuid, '68d26472-f0a4-55c0-ae9d-75ad6c35387f'::uuid), ('a8b1f487-8bfc-53e9-b73a-144686ba9a86'::uuid, '8928c626-36a6-542b-80d6-dcadd03aeb18'::uuid), ('07144595-a590-5495-b4a8-956d301ee7c5'::uuid, 'd0ef8bf7-47c1-5a38-ad86-97dc731ee387'::uuid), ('2fca5dbc-3fd4-5a84-8ac3-e3c9842b35ea'::uuid, '8c3e62cb-8a17-5817-8c13-8277ceb1ac35'::uuid), ('9d0d0f5a-16a9-5268-b099-77298d0521a4'::uuid, '475d486e-63fd-5172-8bb0-cce8625f51d5'::uuid), ('f47a45f1-1ba6-5b40-9a22-ca2dc3e0fbc4'::uuid, '279ee1b6-ae58-5d95-8560-efccbc1de018'::uuid), ('12bc90b7-44df-5d7d-8a21-e6b73d548b36'::uuid, '26753ad5-3ea9-5638-8bea-2e9f2034e034'::uuid), ('ae8c0e40-9cbe-5993-a930-7577622b5316'::uuid, 'e0580215-c402-54c6-8f7e-147c51190d07'::uuid), ('5993795f-77d8-5ff6-950e-c45a53d1b871'::uuid, 'e5106904-3f0f-580f-a956-cdc78775c420'::uuid), ('a2d1897d-1543-571e-95bf-33ece1fd8758'::uuid, '16636952-0788-5fd8-95c0-4e2df96ed1f6'::uuid), ('cec60ddb-c4f8-5e1d-acc9-134c31a5a353'::uuid, 'cdb83410-3991-5585-b12f-10df9d60c68b'::uuid), ('98741097-8c77-57b3-952b-743571d051e2'::uuid, 'b1322418-06f8-4942-8b32-d2e09e90f4e9'::uuid), ('60291908-0686-542f-b3c1-b2fe7e28d5ec'::uuid, '0f7ab3ee-ee41-5427-94ff-b37148a56d18'::uuid), ('1aa54c26-0b5b-5564-823c-7b5f58be0d9e'::uuid, '067cdd71-ea91-5869-b63f-39c0d44d844b'::uuid), ('78d592e2-750c-5f5b-aa13-94434ec6f669'::uuid, '686e6290-331b-5f64-8cee-271847bcc909'::uuid), ('edc68eb6-3488-54eb-aeef-1012a669c1fb'::uuid, 'ce18d3ef-ad16-571a-abc3-7eda8b20c8db'::uuid), ('8e0b0e80-f682-5f36-b204-f9540a8b6bd2'::uuid, '13e52de7-720b-5f3a-b3cf-b6e7b61af755'::uuid), ('5b50ce24-88d6-5243-a79c-b6b8753b1543'::uuid, '0a264306-d97a-5973-8a11-044375e1dda9'::uuid), ('97c6e573-e48f-5e9b-9da2-06d67ef6f74a'::uuid, '309619a8-d4db-54ce-bd7c-7460fb3190a9'::uuid), ('6e78a1ec-3af9-521b-9035-95b6588b4034'::uuid, 'd8a607e5-d3a8-5bc9-8cf8-e5cc68357517'::uuid), ('07a9ce3f-30bc-594d-b1a3-32ef7090aa69'::uuid, '6f27cbb4-0128-50e6-b84d-cdad8e1384fa'::uuid), ('41e6c5a2-09dd-563e-a329-acd5b6897dd8'::uuid, '5b00e28a-b525-54e9-9d03-72121b0b57d8'::uuid), ('31abbc17-9925-52be-be6b-497699266321'::uuid, '88e25771-19e5-5536-bd34-5000decee6c8'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated director row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two divisions of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X-CA-SPD'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X-CA-SPD'
   WHERE a.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid) AND a.geo_id LIKE '%-div-%' AND c.geo_id LIKE '%-div-%' AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% division pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> LOCAL district -> office -> holder)
  -- to exactly that district's own director(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X-CA-SPD'
   WHERE me.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'LOCAL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X-CA-SPD'
             AND (d.geo_id LIKE '%-div-%') = (me.geo_id LIKE '%-div-%')
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id AND och.politician_id IS NOT NULL);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own director(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid);
  IF n <> 3 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 3 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid);
  IF n <> 11 THEN RAISE EXCEPTION 'expected 11 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a director seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('d2803c61-4cd8-5dcb-875a-8182553cf59f'::uuid, '231632e1-9533-5dfc-a4c3-f4c947307af0'::uuid, 'dc11720e-2a64-5acd-9785-8232c6d60a89'::uuid, 'dd646a3a-68f8-5c08-9163-73b002809c12'::uuid, '50d4335e-ae81-57e1-a326-e3ffe9768d64'::uuid, '1942b3aa-4613-56e5-8756-90c06fe84665'::uuid, 'e44a91fa-75d1-5461-af81-0e47ee8b1a4c'::uuid, 'b78acfcb-4790-541c-8539-55f84dda6733'::uuid, 'f4b616c4-cedf-54fd-9e18-36c936f201d1'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated director', n; END IF;

  RAISE NOTICE 'CA_0244 applied: 9 boards, 27 polygons, 43 seats (42 held), 3 races, 11 candidates';
END $$;

COMMIT;
